55 | /**
56 |  * `--author` git-style: `Name <address>` → both verbatim; a bare name gets
57 |  * the deterministic machine address `<slug>@users.noreply.fragmt` – the
58 |  * convention git itself uses, never a real address. Plain commit-metadata
59 |  * plumbing: the value replaces localUser() for the mutation, so the commit
60 |  * AND the sidecar's author field carry the agent's display name.
61 |  */
62 | export function parseAuthor(who: string): { name: string; email: string } {
63 | 	const withAddress = who.trim().match(/^(.*)<([^<>]*)>$/);
64 | 	if (withAddress)
65 | 		return { name: withAddress[1].trim(), email: withAddress[2].trim() };
66 | 	const name = who.trim();
67 | 	return { name, email: `${authorSlug(name)}@users.noreply.fragmt` };
68 | }
