70 | /**
71 |  * The merge commit's identity seam (#43): mergeToMain commits through git's
72 |  * own `merge --no-edit`, which takes no author – but env outranks config, and
73 |  * env is how commitAs already carries identity. Set process-wide for the one
74 |  * call, restored after: the CLI is one-shot and the tests run sequentially.
75 |  * Undefined passes through untouched (the machine identity, as before).
76 |  */
77 | async function mergeAs<T>(
78 | 	user: { name: string; email: string } | undefined,
79 | 	run: () => Promise<T>,
80 | ): Promise<T> {
81 | 	if (user === undefined) return run();
82 | 	const env = {
83 | 		GIT_AUTHOR_NAME: user.name,
84 | 		GIT_AUTHOR_EMAIL: user.email,
85 | 		GIT_COMMITTER_NAME: user.name,
86 | 		GIT_COMMITTER_EMAIL: user.email,
87 | 	};
88 | 	Object.assign(process.env, env);
89 | 	try {
90 | 		return await run();
91 | 	} finally {
92 | 		for (const k of Object.keys(env)) delete process.env[k];
93 | 	}
94 | }
