 65 | /** The main branch name: "main" → "master" → null (rev-parse --verify). */
 66 | export async function mainBranch(repoRoot: string): Promise<string | null> {
 67 | 	for (const name of ["main", "master"]) {
 68 | 		const exists = await git(repoRoot, [
 69 | 			"rev-parse",
 70 | 			"--verify",
 71 | 			"--quiet",
 72 | 			name,
 73 | 		]).then(
 74 | 			() => true,
 75 | 			() => false,
 76 | 		);
 77 | 		if (exists) return name;
 78 | 	}
 79 | 	return null;
 80 | }
