 82 | /**
 83 |  * Unit-separator record parser shared by the `%x1e`-terminated log walks:
 84 |  * a line containing the unit separator opens a commit record; every non-empty
 85 |  * line after it is one of that commit's file paths (git emits the meta line,
 86 |  * a blank line, then the paths – blank separators dropped here).
 87 |  */
 88 | function logRecords(out: string): { fields: string[]; paths: string[] }[] {
 89 | 	const records: { fields: string[]; paths: string[] }[] = [];
 90 | 	for (const raw of out.split("\n")) {
 91 | 		const line = raw.replaceAll("\x1e", "");
 92 | 		if (line.includes("\x1f")) {
 93 | 			records.push({ fields: line.split("\x1f"), paths: [] });
 94 | 		} else if (line !== "" && records.length > 0) {
 95 | 			records[records.length - 1].paths.push(line);
 96 | 		}
 97 | 	}
 98 | 	return records;
 99 | }
