31 | /**
32 |  * A comment body with known doc paths as in-app links (M4-2): split on the
33 |  * known path list, longest first so overlapping paths can't half-match, with
34 |  * a word-boundary-ish guard so "a.md" doesn't fire inside "beta.md".
35 |  * ponytail: regex rebuilt per render – the rail holds a handful of bodies.
36 |  */
37 | function DocRefText({
38 | 	text,
39 | 	docs,
40 | 	onOpenDoc,
41 | }: {
42 | 	text: string;
43 | 	docs: AtDoc[];
44 | 	onOpenDoc: (path: string) => void;
45 | }) {
46 | 	const paths = docs
47 | 		.map((d) => d.path)
48 | 		.filter(Boolean)
49 | 		.sort((a, b) => b.length - a.length);
50 | 	if (paths.length === 0 || !text) return <>{text}</>;
51 | 	const re = new RegExp(`(?<![\\w/.-])(${paths.map(escapeRe).join("|")})`, "g");
52 | 	const out: ReactNode[] = [];
53 | 	let last = 0;
54 | 	for (const m of text.matchAll(re)) {
55 | 		const i = m.index ?? 0;
56 | 		if (i > last) out.push(text.slice(last, i));
57 | 		out.push(
58 | 			<button
59 | 				type="button"
60 | 				className="doc-ref"
61 | 				key={`${m[0]}@${i}`}
62 | 				onClick={() => onOpenDoc(m[0])}
63 | 			>
64 | 				{m[0]}
65 | 			</button>,
66 | 		);
67 | 		last = i + m[0].length;
68 | 	}
69 | 	if (out.length === 0) return <>{text}</>;
70 | 	out.push(text.slice(last));
71 | 	return <>{out}</>;
72 | }
